// Сбор данных и ОБЕЗЛИЧИВАНИЕ запроса к провайдеру.
// На вход: ответ Espo (fullResponse); KPI берём из ноды «Портал: KPI недели».
// На выход — один элемент: { ok, error, body, week_label, removed, model }.
const P = $('Параметры').first().json;
if (!P.chat_id || String(P.chat_id).includes('REPLACE')) {
  return [{ json: { ok: false, error: 'Параметры → chat_id не задан (TELEGRAM_CHAT_ID)' } }];
}
const fail = (error) => [{ json: { ok: false, error, week_label: P.week_label } }];

// --- Портал: KPI недели
const kpiResp = $('Портал: KPI недели').first().json;
if (kpiResp.error || Number(kpiResp.statusCode) !== 200 || !kpiResp.body || !Array.isArray(kpiResp.body.metrics)) {
  const why = kpiResp.error ? (kpiResp.error.message || JSON.stringify(kpiResp.error)) : `HTTP ${kpiResp.statusCode}`;
  return fail(`Портал не отдал KPI недели (${why})`);
}
const kpi = kpiResp.body;

// --- Espo: отклики недели. Берём ТОЛЬКО статус, источник, даты и бюджет — имён/контактов в запросе нет.
const espoResp = $input.first().json;
if (espoResp.error || Number(espoResp.statusCode) !== 200 || !espoResp.body) {
  const why = espoResp.error ? (espoResp.error.message || JSON.stringify(espoResp.error)) : `HTTP ${espoResp.statusCode}`;
  return fail(`Espo не отдал отклики недели (${why})`);
}
const leads = Array.isArray(espoResp.body.list) ? espoResp.body.list : [];

// --- Месячный потолок токенов: считаем в staticData, при превышении — не вызываем провайдера.
const store = $getWorkflowStaticData('global');
store.usage = store.usage || {};
const month = DateTime.now().setZone('Europe/Moscow').toFormat('yyyy-MM');
const spent = Number(store.usage[month] || 0);
const cap = Number(P.monthly_token_cap || 0);
if (cap > 0 && spent >= cap) {
  return fail(`месячный потолок токенов исчерпан (${spent} из ${cap}); поднять monthly_token_cap в Параметрах`);
}

// --- Сводка по откликам: по площадкам, статусам, скорости ответа и бюджетам
const bySource = {};
let responded24 = 0, respondedTotal = 0;
for (const l of leads) {
  const s = l.source || 'other';
  const b = bySource[s] = bySource[s] || { n: 0, statuses: {}, budgets: [] };
  b.n += 1;
  const st = l.status || '—';
  b.statuses[st] = (b.statuses[st] || 0) + 1;
  if (l.cBudget) b.budgets.push(String(l.cBudget));
  if (l.cRespondedAt && l.createdAt) {
    respondedTotal += 1;
    const h = (Date.parse(l.cRespondedAt.replace(' ', 'T') + 'Z') - Date.parse(l.createdAt.replace(' ', 'T') + 'Z')) / 3600000;
    if (h >= 0 && h <= 24) responded24 += 1;
  }
}
const srcLines = Object.entries(bySource).map(([s, b]) => {
  const st = Object.entries(b.statuses).map(([k, v]) => `${k} ${v}`).join(', ');
  const bud = b.budgets.length ? `; бюджеты: ${b.budgets.slice(0, 5).join(', ')}` : '';
  return `- ${s}: ${b.n} (статусы: ${st}${bud})`;
});

const metricLines = kpi.metrics.map((m) => {
  const goal = m.target != null ? ` из ${m.target}` : '';
  const okTxt = m.ok === true ? ' — цель достигнута' : m.ok === false ? ' — цель не достигнута' : '';
  return `- ${m.title}: ${m.value}${goal}${okTxt}${m.detail && m.target == null ? ` (${m.detail})` : ''}`;
});

let userText = [
  `Неделя: ${P.week_label}.`,
  'KPI (из портала):', ...metricLines,
  `Отклики из CRM за неделю: ${leads.length}${respondedTotal ? `; ответ клиенту дан по ${respondedTotal}, из них в первые 24 ч — ${responded24}` : ''}.`,
  'По площадкам:', ...(srcLines.length ? srcLines : ['- откликов нет']),
].join('\n');

// --- Обезличивание: телефоны, e-mail, ИНН вырезаем регулярными выражениями (в тексте их быть не должно,
// но бюджет — свободное поле, а KPI detail — строка: страхуемся).
const PII = [
  /\+?\d[\d\s\-()]{9,}\d/g,             // телефон
  /[\w.+-]+@[\w-]+\.[\w.-]+/g,           // e-mail
  /\b\d{10}(\d{2})?\b/g,                 // ИНН 10/12 цифр
];
let removed = 0;
for (const re of PII) userText = userText.replace(re, () => { removed += 1; return '<вырезано>'; });
if (removed > 0) userText += `\n(вырезано: ${removed} фрагментов)`;

const systemText = 'Ты помогаешь фрилансеру-автоматизатору написать недельный отчёт руководителю компании. '
  + 'Пиши коротко, по-русски, 6–10 строк, деловым тоном от первого лица. Используй только факты из переданных данных, '
  + 'ничего не выдумывай и не добавляй рекомендаций, которых нет в данных. '
  + 'Формат: заголовок «Отчёт за неделю ДД.ММ–ДД.ММ», затем строки по метрикам и откликам, затем одна строка '
  + '«Фокус на следующую неделю» — только если в данных есть невыполненная цель.';

const folder = $env.YANDEX_FOLDER_ID;
if (!folder) return fail('YANDEX_FOLDER_ID не задан в окружении n8n');
const body = {
  modelUri: `gpt://${folder}/${P.model}/latest`,
  completionOptions: { stream: false, temperature: 0.2, maxTokens: '1500' },
  messages: [{ role: 'system', text: systemText }, { role: 'user', text: userText }],
};
return [{ json: { ok: true, body, week_label: P.week_label, removed, model: P.model, prompt_chars: userText.length } }];

// Разбор ответа Яндекса, учёт usage, текст для Telegram.
const P = $('Параметры').first().json;
const req = $('Обезличивание').first().json;
const r = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (r.error || Number(r.statusCode) !== 200) {
  const why = r.error ? (r.error.message || JSON.stringify(r.error))
    : `HTTP ${r.statusCode}${r.body && r.body.error ? ': ' + (r.body.error.message || r.body.error) : ''}`;
  return [{ json: { ok: false, error: `провайдер ИИ (${req.model}) — ${why}` } }];
}
const res = r.body && r.body.result;
const alt = res && res.alternatives && res.alternatives[0];
const draft = alt && alt.message && alt.message.text ? alt.message.text.trim() : '';
if (!draft) return [{ json: { ok: false, error: 'провайдер вернул пустой ответ' } }];

// usage → лог сценария и месячный счётчик
const usage = (res && res.usage) || {};
const total = Number(usage.totalTokens || 0);
const store = $getWorkflowStaticData('global');
store.usage = store.usage || {};
const month = DateTime.now().setZone('Europe/Moscow').toFormat('yyyy-MM');
store.usage[month] = Number(store.usage[month] || 0) + total;
console.log(JSON.stringify({ scenario: 'weekly-report', model: req.model, modelVersion: res.modelVersion,
  inputTextTokens: usage.inputTextTokens, completionTokens: usage.completionTokens, totalTokens: total,
  month_total: store.usage[month], removed_pii: req.removed }));

const text = [
  `📝 <b>Черновик отчёта руководителю</b> (${esc(req.week_label)})`,
  '',
  esc(draft),
  '',
  `<i>${esc(req.model)} · ${total} токенов · за месяц ${store.usage[month]}${P.monthly_token_cap ? ' из ' + P.monthly_token_cap : ''}`
    + (req.removed ? ` · вырезано ПДн: ${req.removed}` : '') + '</i>',
].join('\n');
return [{ json: { ok: true, chat_id: String(P.chat_id), text } }];
